import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"離下乾上 同人：","description":"京氏易傳 - 離下乾上 同人：","frontmatter":{"title":"離下乾上 同人：","description":"京氏易傳 - 離下乾上 同人："},"headers":[],"relativePath":"classics/jingshi/057.md","filePath":"classics/jingshi/057.md"}'),r={name:"classics/jingshi/057.md"};function l(c,a,o,d,p,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"離下乾上-同人",tabindex:"-1"},[i("離下乾上 同人： "),e("a",{class:"header-anchor",href:"#離下乾上-同人","aria-label":"Permalink to “離下乾上 同人：”"},"​")],-1),e("p",null,"二氣同進，健而炎上，【乾務上，離務下。】同途異致，性則合也。《易》曰：“出門同人，又誰咎也”。（虎易注：初九象辭。）九二得位居中，六三積陰待應。（虎易注:此兩句疑為有誤。）《易》曰：“先號咷而後笑”。（虎易注：九五爻辭。）【隔於陽位，不能決勝，先故曰號咷；後獲合方喜也，故曰後笑也。】八卦復位，六爻遷次，週而復始。上下不停，生生之義，易道祖也。天與火，明而健；陽道正，陰氣和也。【六二居內卦中，能奉於陽。】吉凶故象，五行昭然。【金木水火土，配六位相生。】與坎為飛伏。【己亥水，戊午火。】歸魂立三公為世，上九宗廟為應候。",-1),e("p",null,"建始丁巳至壬戌，【小滿，寒露。】積算起壬戌至辛酉，週而復始。火土入乾離。【火土二象入乾離，配六宮起積算。】",-1),e("p",null,"五星從位起鎮星，【土星入卦，定其吉凶。】觜宿從位降己亥水，【二十八宿，分觜宿入離歸魂，配天火同人九三己亥水上。】分氣候二十八。【起積算二十八位數，巡六爻有吉凶入何位。】",-1),e("p",null,"火上見金，二氣雖同，五行相悖。六爻定位，吉凶之兆在乎五二，得時則順，失時則逆。陰陽升降，歲月分焉，爻象相蕩，內外適變，八卦巡迴，歸魂複本。本靜則象生，故適離為兌入少女，分八卦於兌象。【坎入兌宮八卦。】（虎易注：坎字應為降，遷字之誤。）",-1)])])}const h=s(r,[["render",l]]);export{f as __pageData,h as default};
